import {Renderer as CampRenderer} from './renderer.js';
import {BUILDINGS} from './data.js';
import {FRONTIER_RECTS,CANAL,ECO,COVER} from './frontier-data.js';
export class Renderer extends CampRenderer{
 frontierSprite(index,x,y,w=50,h=65,alpha=1){const rect=FRONTIER_RECTS[index],img=this.assets.frontier;if(!rect||!img)return;const c=this.ctx,k=Math.min(w/rect[2],h/rect[3]);c.save();c.globalAlpha=alpha;c.drawImage(img,...rect,x-rect[2]*k/2,y-rect[3]*k,rect[2]*k,rect[3]*k);c.restore();}
 drawFarm(engine){super.drawFarm(engine);const c=this.ctx,f=engine.f;c.save();for(const room of engine.rooms()){const p=room.floor;c.fillStyle='#7f684994';c.fillRect(p.x-56,p.y-48,112,96);c.strokeStyle=room.active?'#c5ba7e':'#867f61';c.strokeRect(p.x-56,p.y-48,112,96);for(let y=p.y-48;y<p.y+48;y+=16){c.beginPath();c.moveTo(p.x-56,y);c.lineTo(p.x+56,y);c.stroke();}this.text(room.type,p.x,p.y+62,room.active?'#f0dfa4':'#bdba9c',12);}
 const flow=engine.canalFlow();for(let i=0;i<16;i++){const x=CANAL.x+i%4*CANAL.size,y=CANAL.y+Math.floor(i/4)*CANAL.size;this.drawCanalCell(x,y,flow.includes(i)?'flow':f.canals.dug.includes(i)?'dug':'none',i);}this.text('水渠 · '+f.canals.level+'/3',CANAL.x+56,CANAL.y+126,'#c1e0df',12);if(f.canals.level>=2){c.fillStyle='#5d9aabb0';c.fillRect(870,748,76,22);this.text('浅滩积水',908,780,'#badddf',11);}
 for(const [i,t]of f.ecology.entries()){const x=ECO.x+i%4*ECO.size,y=ECO.y+Math.floor(i/4)*ECO.size;this.drawEcoCell(x,y,t,i);}this.text('生态修复 · '+f.ecology.filter(t=>t.clean).length+'/16',ECO.x+56,ECO.y+128,'#c9d6ae',12);for(const [i,id]of f.species.entries()){const index={butterfly:1,frog:2,egret:3}[id];this.frontierSprite(index,ECO.x+24+i*40+Math.sin(this.time*(id==='butterfly'?2:1))*5,ECO.y+53+(id==='butterfly'?Math.sin(this.time*3)*8:0),id==='egret'?36:25,id==='egret'?55:30);}
 if(f.soilView)for(const p of engine.s.plots)this.badge(String(Math.round(p.fertility)),p.x,p.y+13,p.fertility<30?'#e5b095':'#e0e7b8');c.restore();}
 drawCanalCell(x,y,state){const c=this.ctx;c.fillStyle=state==='flow'?'#68a9b0bf':state==='dug'?'#463b2dde':'#9b986733';c.fillRect(x,y,26,26);c.strokeStyle='#d2d0a345';c.strokeRect(x,y,26,26);}
 drawEcoCell(x,y,t){const c=this.ctx;c.fillStyle=!t.clean?'#725572b0':({grass:'#77a150a0',forest:'#385f43bb',wetland:'#538d98b0',field:'#8d714f80',empty:'#5e73467a'}[t.type]);c.fillRect(x,y,26,26);c.strokeStyle='#d6d9b431';c.strokeRect(x,y,26,26);if(t.type==='forest')this.frontierSprite(13,x+13,y+26,25,36);if(t.type==='wetland')this.frontierSprite(12,x+13,y+26,24,30);}
 drawRuins(engine){super.drawRuins(engine);if(engine.s.region==='market')return;const c=this.ctx;c.save();for(const r of COVER){c.fillStyle='#59774845';c.fillRect(r.x,r.y,r.w,r.h);for(let x=r.x+15;x<r.x+r.w;x+=35)this.frontierSprite(12,x,r.y+r.h*.7,36,42,.65);}const t=engine.f.dog.tracking;if(t?.region===engine.s.region&&!t.revealed){c.strokeStyle='#bdd59a88';c.setLineDash([3,12]);c.lineWidth=3;c.beginPath();c.moveTo(engine.f.dog.x,engine.f.dog.y);for(const p of t.path)c.lineTo(p.x,p.y);c.stroke();}c.restore();}
 drawObject(o,engine){if(o.type==='partnerDog'){this.shadow(o.x,o.y,16);this.frontierSprite(0,o.x,o.y,49,48);this.text('麦穗',o.x,o.y-57,'#e6d2a7',11);return;}if(o.frontierIcon!=null){this.shadow(o.x,o.y,19);this.frontierSprite(o.frontierIcon,o.x,o.y,o.type==='waterGate'?48:42,o.type==='dogRescue'?46:55);this.text(o.name,o.x,o.y-69,'#e0d2a9',11);return;}return super.drawObject(o,engine);}
 drawBuilding(b,engine){const d=BUILDINGS[b.type];if(b.type==='floor')return;if(d.frontierIcon!=null){this.shadow(b.x,b.y,18);this.frontierSprite(d.frontierIcon,b.x,b.y,d.w+18,b.type==='lamp'?72:60,b.hp>0?1:.35);if(Math.hypot(engine.s.player.x-b.x,engine.s.player.y-b.y)<95)this.text(d.name,b.x,b.y-72,'#e5d7b0',11);if(b.hp<d.hp)this.text(b.hp<=0?'待维修':Math.ceil(b.hp)+'/'+d.hp,b.x,b.y+10,'#dcb78d',11);return;}return super.drawBuilding(b,engine);}
 drawEnemy(e,engine){if(e.nest){this.shadow(e.x,e.y,30);this.frontierSprite(8,e.x,e.y,82,86,e.flash?.5:1);this.badge('感染巢 · '+Math.max(0,Math.ceil(e.hp))+'/'+e.maxHp,e.x,e.y-98,'#e6ada0');return;}super.drawEnemy(e,engine);const c=this.ctx;if(e.awareness>0&&e.awareness<1){c.fillStyle='#23322bdd';c.fillRect(e.x-20,e.y-90,40,5);c.fillStyle='#e4c780';c.fillRect(e.x-20,e.y-90,40*e.awareness,5);this.text('警戒',e.x,e.y-100,'#e5d6aa',10);}if(e.type==='elite'){const part=engine.f.aimPart,names={armor:'装甲',legs:'腿部',pack:'背包',core:'核心'};this.badge('瞄准 '+names[part]+' · T切换',e.x,e.y-130,'#eac99e');if(e.parts){this.text('甲'+Math.ceil(e.parts.armor)+' 腿'+Math.ceil(e.parts.legs)+' 包'+Math.ceil(e.parts.pack),e.x,e.y-148,'#d9bba7',11);}}}
 drawPlayer(engine){super.drawPlayer(engine);if(engine.f.crouch)this.badge(engine.inCover()?'草丛隐蔽':'蹲行',engine.s.player.x,engine.s.player.y+20,'#cbdda5');}
 draw(engine,mouse,dt=.016){super.draw(engine,mouse,dt);const c=this.ctx,f=engine.f;c.save();c.setTransform(this.dpr,0,0,this.dpr,0,0);if(f.camera){const rect=this.photoFrame();c.strokeStyle='#e5d7aabf';c.lineWidth=2;for(const [x,y,sx,sy]of [[rect.x,rect.y,1,1],[rect.x+rect.w,rect.y,-1,1],[rect.x,rect.y+rect.h,1,-1],[rect.x+rect.w,rect.y+rect.h,-1,-1]]){c.beginPath();c.moveTo(x+sx*25,y);c.lineTo(x,y);c.lineTo(x,y+sy*25);c.stroke();}this.badge('H 拍照 · 最近6张保留',this.w/2,rect.y-14,'#e8dfb7');}const photo=f.photos.find(p=>p.id===f.displayPhoto);if(photo&&engine.s.region==='farm'&&engine.paused&&this.w>650){this.photoImages??=new Map();let img=this.photoImages.get(photo.id);if(!img&&typeof Image!=='undefined'){img=new Image();img.src=photo.data;this.photoImages.set(photo.id,img);}if(img?.complete){const x=26,y=this.h-342;c.fillStyle='#997449';c.fillRect(x-4,y-4,150,74);c.drawImage(img,x,y,142,66);this.text('营地相片',x+71,y-13,'#ddcfaa',11);}}c.restore();}
 photoFrame(){return {x:this.w*.16,y:this.h*.08,w:this.w*.68,h:this.h*.80};}
 photoWorldRect(){const frame=this.photoFrame(),a=this.worldPoint(frame.x,frame.y);return {x:a.x,y:a.y,w:frame.w/this.camera.scale,h:frame.h/this.camera.scale};}
}
